<?php if($experiments):?><section class="editorial-experiments" aria-labelledby="experiment-heading"><span class="eyebrow">Question → test → decision</span><h2 id="experiment-heading">Experiment and decision log.</h2><p>Published entries show the question, what was tried and what the evidence supports. Planned work is labelled as planned.</p>
<?php foreach($experiments as $experiment):?><article class="editorial-experiment" id="experiment-<?=(int)$experiment['id']?>"><div class="journey-meta"><span class="journey-badge"><?=e(editorial_experiment_states()[$experiment['experiment_state']]??'')?></span><time datetime="<?=e(date(DATE_ATOM,strtotime($experiment['published_at'])))?>"><?=e(format_date($experiment['published_at']))?></time></div><h3><?=e($experiment['title'])?></h3><p><?=e($experiment['summary'])?></p><dl><?php foreach(['question','hypothesis','method','findings','decision','limitations','next_step'] as $key):?><?php if(!empty($experiment[$key])):?><dt><?=e(ucfirst(str_replace('_',' ',$key)))?></dt><dd><?=nl2br(e($experiment[$key]))?></dd><?php endif;?><?php endforeach;?></dl><?php if(!empty($experiment['evidence_url'])):?><a class="text-link" href="<?=e($experiment['evidence_url'])?>" rel="noopener noreferrer">Read the public evidence ↗</a><?php endif;?></article><?php endforeach;?></section><?php endif;?>
